using System.Text.RegularExpressions;
using System.Net;
using Microsoft.AspNetCore.Mvc.Testing;

namespace SafeVault.Tests
{
    /// <summary>
    /// Integration tests that verify SafeVault authorization
    /// through the ASP.NET Core request pipeline.
    /// </summary>
    public class AuthorizationIntegrationTests
    {
        /// <summary>
        /// Retrieves the antiforgery token generated by the SafeVault
        /// login form so integration tests can submit a valid POST request.
        /// </summary>
        private static async Task<string> GetAntiforgeryTokenAsync(
            HttpClient client)
        {
            var response =
                await client.GetAsync("/Account/Login");

            response.EnsureSuccessStatusCode();

            var html =
                await response.Content.ReadAsStringAsync();

            var match = Regex.Match(
                html,
                @"name=""__RequestVerificationToken""[^>]*value=""([^""]+)""");

            Assert.True(
                match.Success,
                "The login page did not contain an antiforgery token.");

            return match.Groups[1].Value;
        }
        /// <summary>
        /// Confirms that an unauthenticated request to the
        /// Admin Dashboard is redirected to the login page.
        /// </summary>
        [Fact]
        public async Task AdminEndpoint_AnonymousUser_RedirectsToLogin()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress = new Uri("https://localhost")
                    });

            // Act
            var response =
                await client.GetAsync("/Admin");

            // Assert
            Assert.Equal(
                HttpStatusCode.Redirect,
                response.StatusCode);

            Assert.NotNull(
                response.Headers.Location);

            Assert.Equal(
                "/Account/Login",
                response.Headers.Location.AbsolutePath);
        }
        /// <summary>
        /// Confirms that submitting credentials for an unknown username
        /// does not create an authenticated SafeVault session.
        /// </summary>
        [Fact]
        public async Task Login_UnknownUsername_IsRejected()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress = new Uri("https://localhost"),
                        HandleCookies = true
                    });

            var antiforgeryToken =
                await GetAntiforgeryTokenAsync(client);

            using var formContent =
                new FormUrlEncodedContent(
                    new Dictionary<string, string>
                    {
                        ["Username"] = "UnknownSafeVaultUser",
                        ["Password"] = "Incorrect-Password!",
                        ["__RequestVerificationToken"] =
                            antiforgeryToken
                    });

            // Act
            var response =
                await client.PostAsync(
                    "/Account/Login",
                    formContent);

            // Assert
            Assert.Equal(
                HttpStatusCode.OK,
                response.StatusCode);

            var responseHtml =
                await response.Content.ReadAsStringAsync();

            Assert.Contains(
                "Invalid username or password.",
                responseHtml);

            Assert.DoesNotContain(
                ".AspNetCore.Cookies",
                response.Headers.ToString());
        }
        /// <summary>
        /// Confirms that a known SafeVault account cannot authenticate
        /// when an incorrect password is supplied.
        /// </summary>
        [Fact]
        public async Task Login_KnownUserWrongPassword_IsRejected()
        {
            // Arrange
            using var factory =
