        }
        /// <summary>
        /// Confirms that valid SafeVault credentials establish an
        /// authenticated session that can access a protected endpoint.
        /// </summary>
        [Fact]
        public async Task Login_ValidCredentials_AuthenticatesUser()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress = new Uri("https://localhost"),
                        HandleCookies = true
                    });

            var antiforgeryToken =
                await GetAntiforgeryTokenAsync(client);

            using var formContent =
                new FormUrlEncodedContent(
                    new Dictionary<string, string>
                    {
                        ["Username"] = "SafeVaultUser",
                        ["Password"] = "SafeVault-User-2026!",
                        ["__RequestVerificationToken"] =
                            antiforgeryToken
                    });

            // Act
            var loginResponse =
                await client.PostAsync(
                    "/Account/Login",
                    formContent);

            // Assert: successful login redirects to LoginSuccess.
            Assert.Equal(
                HttpStatusCode.Redirect,
                loginResponse.StatusCode);

            Assert.NotNull(
                loginResponse.Headers.Location);

            Assert.Equal(
            "/Account/LoginSuccess",
            loginResponse.Headers.Location.OriginalString);

            // Act: use the authentication cookie retained by the client
            // to request an endpoint that requires authentication.
            var protectedResponse =
                await client.GetAsync(
                    "/Account/LoginSuccess");

            // Assert
            Assert.Equal(
                HttpStatusCode.OK,
                protectedResponse.StatusCode);

            var responseHtml =
                await protectedResponse.Content.ReadAsStringAsync();

            Assert.Contains(
                "SafeVaultUser",
                responseHtml);
        }
        /// <summary>
        /// Confirms that an authenticated SafeVault user without the
        /// admin role cannot access the Admin Dashboard.
        /// </summary>
        [Fact]
        public async Task AdminEndpoint_AuthenticatedUser_IsDenied()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress = new Uri("https://localhost"),
                        HandleCookies = true
                    });

            var antiforgeryToken =
                await GetAntiforgeryTokenAsync(client);

            using var formContent =
                new FormUrlEncodedContent(
                    new Dictionary<string, string>
                    {
                        ["Username"] = "SafeVaultUser",
                        ["Password"] = "SafeVault-User-2026!",
                        ["__RequestVerificationToken"] =
                            antiforgeryToken
                    });

            // Act: authenticate as the ordinary user.
            var loginResponse =
                await client.PostAsync(
                    "/Account/Login",
                    formContent);

            // Assert: confirm authentication succeeded first.
            Assert.Equal(
                HttpStatusCode.Redirect,
                loginResponse.StatusCode);

            Assert.NotNull(
                loginResponse.Headers.Location);

            Assert.Equal(
                "/Account/LoginSuccess",
                loginResponse.Headers.Location.OriginalString);

            // Act: attempt to access the admin-only resource using
            // the authenticated user's retained cookie.
            var adminResponse =
                await client.GetAsync("/Admin");

            // Assert: the authenticated user must not reach
            // the Admin Dashboard.
            Assert.Equal(
                HttpStatusCode.Redirect,
                adminResponse.StatusCode);

            Assert.NotNull(
                adminResponse.Headers.Location);

            Assert.Equal(
                "/Account/AccessDenied",
                adminResponse.Headers.Location.AbsolutePath);
        }
        /// <summary>
        /// Confirms that an authenticated SafeVault account assigned
        /// to the admin role can access the Admin Dashboard.
        /// </summary>
        [Fact]
        public async Task AdminEndpoint_AuthenticatedAdmin_IsAllowed()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress = new Uri("https://localhost"),
                        HandleCookies = true
                    });

            var antiforgeryToken =
                await GetAntiforgeryTokenAsync(client);

            using var formContent =
                new FormUrlEncodedContent(
                    new Dictionary<string, string>
                    {
                        ["Username"] = "SafeVaultAdmin",
                        ["Password"] = "SafeVault-Admin-2026!",
                        ["__RequestVerificationToken"] =
                            antiforgeryToken
                    });

            // Act: authenticate as the administrator.
            var loginResponse =
                await client.PostAsync(
                    "/Account/Login",
                    formContent);

            // Assert: verify that authentication succeeded.
            Assert.Equal(
                HttpStatusCode.Redirect,
                loginResponse.StatusCode);

            Assert.NotNull(
                loginResponse.Headers.Location);

            Assert.Equal(
                "/Account/LoginSuccess",
                loginResponse.Headers.Location.OriginalString);

            // Act: request the admin-only resource using the
            // authentication cookie retained by the test client.
            var adminResponse =
                await client.GetAsync("/Admin");

            // Assert: the admin account is authorized.
            Assert.Equal(
                HttpStatusCode.OK,
                adminResponse.StatusCode);

            var responseHtml =
                await adminResponse.Content.ReadAsStringAsync();

            Assert.Contains(
                "Admin Dashboard",
                responseHtml);

            Assert.Contains(
                "SafeVaultAdmin",
                responseHtml);

            Assert.Contains(
                "True",
                responseHtml);
        }
    }
}